defmodule Ros2Zenoh.FoxgloveMsgs.Msg.Point2 do
  @moduledoc """
  `foxglove_msgs/Point2`: two `float64`s. In an image annotation these
  are **pixel** coordinates, not metres.
  """
  use Ros2Zenoh.Common

  defstruct x: 0.0, y: 0.0

  def msg_definition do
    """
    # foxglove_msgs/msg/Point2
    # A point representing a position in 2D space

    # Generated by https://github.com/foxglove/foxglove-sdk

    # x coordinate position
    float64 x

    # y coordinate position
    float64 y
    """
  end

  def dependencies, do: []

  def encode(%__MODULE__{x: x, y: y}), do: encode_float64(x) <> encode_float64(y)
end
